// About page — personal, editorial layout
import React from 'react';
import { Link } from 'react-router-dom';
import './About.css';

const interests = [
  { icon: 'server', title: 'Backend systems', text: 'Designing services that stay fast and correct under real load.' },
  { icon: 'flow', title: 'Distributed data', text: 'Streaming, pipelines, and moving data reliably at scale.' },
  { icon: 'cloud', title: 'Cloud', text: 'Building cost-aware systems on AWS and GCP.' },
  { icon: 'book', title: 'Learning in public', text: 'Writing about what I read and figure out along the way.' },
];

// Clean, consistent line icons (stroke uses currentColor = accent).
const Icon = ({ name }) => {
  const common = {
    width: 22,
    height: 22,
    viewBox: '0 0 24 24',
    fill: 'none',
    stroke: 'currentColor',
    strokeWidth: 1.7,
    strokeLinecap: 'round',
    strokeLinejoin: 'round',
  };
  switch (name) {
    case 'server':
      return (
        <svg {...common}>
          <rect x="3" y="4" width="18" height="7" rx="1.5" />
          <rect x="3" y="13" width="18" height="7" rx="1.5" />
          <line x1="7" y1="7.5" x2="7" y2="7.5" />
          <line x1="7" y1="16.5" x2="7" y2="16.5" />
        </svg>
      );
    case 'flow':
      return (
        <svg {...common}>
          <circle cx="6" cy="6" r="2.5" />
          <circle cx="18" cy="6" r="2.5" />
          <circle cx="12" cy="18" r="2.5" />
          <path d="M7.5 8 L11 15.5 M16.5 8 L13 15.5 M8.5 6 H15.5" />
        </svg>
      );
    case 'cloud':
      return (
        <svg {...common}>
          <path d="M7 18h10a4 4 0 0 0 .5-7.97A5.5 5.5 0 0 0 6.8 9 3.5 3.5 0 0 0 7 18Z" />
        </svg>
      );
    case 'book':
      return (
        <svg {...common}>
          <path d="M4 5a2 2 0 0 1 2-2h13v16H6a2 2 0 0 0-2 2Z" />
          <path d="M4 19a2 2 0 0 1 2-2h13" />
        </svg>
      );
    default:
      return null;
  }
};

const facts = [
  { k: 'Now', v: 'Software Engineer @ HSBC' },
  { k: 'Based in', v: 'Pune, India' },
  { k: 'Working with', v: 'Java · Scala · Kafka · Spark' },
  { k: 'Currently', v: 'Building data platforms' },
];

const About = () => (
  <div className="about">
    {/* Hero: portrait + intro */}
    <section className="about__hero">
      <div className="about__portrait">
        <img src={process.env.PUBLIC_URL + '/avatar.png'} alt="Anantashayana Hegde" />
      </div>

      <div className="about__intro">
        <span className="about__eyebrow">About</span>
        <h1 className="about__name">Anantashayana Hegde</h1>
        <p className="about__lede">
          I’m a software engineer who likes building the quiet machinery behind
          products — backend services, data pipelines, and the systems that keep
          them honest.
        </p>
        <div className="about__actions">
          <a
            className="btn btn--primary"
            href="https://drive.google.com/file/d/1tEN65CfDJmLXSo5AvCqF4Q91rK8UEaFV/view?usp=drive_link"
            target="_blank"
            rel="noopener noreferrer"
          >
            Résumé
          </a>
          <a className="btn btn--ghost" href="https://github.com/Anantashayana" target="_blank" rel="noopener noreferrer">
            GitHub
          </a>
          <a className="btn btn--ghost" href="https://www.linkedin.com/in/anantashayana/" target="_blank" rel="noopener noreferrer">
            LinkedIn
          </a>
        </div>
      </div>
    </section>

    {/* Quick facts strip */}
    <section className="about__facts">
      {facts.map((f) => (
        <div key={f.k} className="about__fact">
          <span className="about__fact-k">{f.k}</span>
          <span className="about__fact-v">{f.v}</span>
        </div>
      ))}
    </section>

    {/* Story */}
    <section className="about__story">
      <p>
        Most of my work lives on the backend — I build and maintain services in
        Java and Scala, wrangle data with Kafka and Spark, and care a lot about
        making systems that are simple to reason about and hard to break.
      </p>
      <p>
        Outside of shipping features, I enjoy the puzzle: untangling a
        scalability bottleneck, redesigning a schema, or bridging two systems
        that were never meant to talk. When I’m not coding, I’m usually reading
        or writing up something I just learned.
      </p>
    </section>

    {/* Interests */}
    <section className="about__section">
      <h2 className="about__h2">What I care about</h2>
      <div className="about__interests">
        {interests.map((it) => (
          <div key={it.title} className="about__interest">
            <span className="about__interest-icon"><Icon name={it.icon} /></span>
            <div>
              <h3>{it.title}</h3>
              <p>{it.text}</p>
            </div>
          </div>
        ))}
      </div>
    </section>

    {/* Closing */}
    <section className="about__closing">
      <p>
        Want to see what I’ve built? Take a look at my{' '}
        <Link to="/projects">projects</Link>, or read the{' '}
        <Link to="/blog">blog</Link>.
      </p>
    </section>
  </div>
);

export default About;
